const selectedRepos = $input.all().map((item) => item.json);
const config = selectedRepos[0] || {};

const parseJsonArray = (value, fieldName) => {
  if (typeof value !== 'string' || value.trim() === '') {
    return [];
  }

  try {
    const parsed = JSON.parse(value);
    if (!Array.isArray(parsed)) {
      throw new Error(`${fieldName} must be a JSON array`);
    }

    return parsed
      .map((entry) => String(entry).trim())
      .filter(Boolean);
  } catch (error) {
    throw new Error(`Invalid ${fieldName}: ${error.message}`);
  }
};

const parsePositiveInteger = (value, fieldName, fallback) => {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }

  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    throw new Error(`${fieldName} must be a positive number`);
  }

  return Math.floor(parsed);
};

const workflowId = String(config.workflowId || '').trim();
if (!workflowId) {
  throw new Error('workflowId is required');
}

const reviewerLogins = new Set(
  parseJsonArray(config.reviewerLoginsJson, 'reviewerLoginsJson').map((entry) =>
    entry.toLowerCase(),
  ),
);
if (reviewerLogins.size === 0) {
  throw new Error('reviewerLoginsJson must contain at least one login');
}

const bootstrapLookbackHours = parsePositiveInteger(
  config.bootstrapLookbackHours,
  'bootstrapLookbackHours',
  24,
);
const maxPullRequestsPerRepo = Math.min(
  parsePositiveInteger(
    config.maxPullRequestsPerRepo,
    'maxPullRequestsPerRepo',
    25,
  ),
  100,
);
const rememberedCommentIds = parsePositiveInteger(
  config.rememberedCommentIds,
  'rememberedCommentIds',
  1000,
);

const staticData = $getWorkflowStaticData('global');
const state = staticData.coderabbitReviewExtraction || {};
const pollStartedAt = new Date().toISOString();
const bootstrapAnchor = new Date(
  Date.now() - bootstrapLookbackHours * 60 * 60 * 1000,
).toISOString();
const pollAfter = typeof state.lastPolledAt === 'string' ? state.lastPolledAt : bootstrapAnchor;

const selectedRepoMap = new Map();
for (const repo of selectedRepos) {
  const fullName = String(repo.github_full_name || repo.githubFullName || '')
    .trim()
    .toLowerCase();

  if (!fullName) {
    continue;
  }

  const projectIds = Array.isArray(repo.projectIds)
    ? repo.projectIds.map((entry) => String(entry))
    : [];
  const projectNames = Array.isArray(repo.projectNames)
    ? repo.projectNames.map((entry) => String(entry))
    : [];

  selectedRepoMap.set(fullName, {
    repoId: String(repo.repo_id || repo.repoId || ''),
    repoName: String(repo.repo_name || repo.repoName || ''),
    displayName: String(repo.display_name || repo.displayName || ''),
    path: String(repo.path || ''),
    githubOwner: String(repo.github_owner || repo.githubOwner || ''),
    githubRepoName: String(repo.github_repo_name || repo.githubRepoName || ''),
    githubFullName: String(repo.github_full_name || repo.githubFullName || ''),
    projectIds,
    projectNames,
  });
}

const normalizedRepos = Array.from(selectedRepoMap.values()).sort((left, right) =>
  left.githubFullName.localeCompare(right.githubFullName),
);

staticData.coderabbitReviewExtractionRun = {
  workflowId,
  pollStartedAt,
  pollAfter,
  selectedRepoCount: normalizedRepos.length,
  selectedReposSummary: normalizedRepos.map((repo) => ({
    repo: repo.githubFullName,
    projects: repo.projectNames,
  })),
  selectedReposByFullName: Object.fromEntries(
    normalizedRepos.map((repo) => [repo.githubFullName.toLowerCase(), repo]),
  ),
  reviewerLogins: Array.from(reviewerLogins),
  rememberedCommentIds,
  knownCommentIds: Array.isArray(state.processedThreadCommentIds)
    ? state.processedThreadCommentIds.map((entry) => String(entry))
    : [],
  newCommentIds: [],
  inaccessibleRepos: [],
  extractedPullRequests: [],
  inspectedPullRequestCount: 0,
  inspectedThreadCount: 0,
};

return normalizedRepos.map((repo) => ({
  json: {
    githubOwner: repo.githubOwner,
    githubRepoName: repo.githubRepoName,
    githubFullName: repo.githubFullName,
    projectNames: repo.projectNames,
    maxPullRequestsPerRepo,
  },
}));

const staticData = $getWorkflowStaticData('global');
const run = staticData.coderabbitReviewExtractionRun || {};
run.inaccessibleRepos ??= [];
run.extractedPullRequests ??= [];
run.newCommentIds ??= [];

const repo = $('Loop Selected Repos').item.json;
const payload = $input.first().json;
const pollAfterMs = Date.parse(String(run.pollAfter || ''));
const reviewerLogins = new Set(
  Array.isArray(run.reviewerLogins)
    ? run.reviewerLogins.map((entry) => String(entry).toLowerCase())
    : [],
);
const knownCommentIds = new Set(
  Array.isArray(run.knownCommentIds)
    ? run.knownCommentIds.map((entry) => String(entry))
    : [],
);

const recordInaccessible = (status, message) => {
  run.inaccessibleRepos.push({
    repo: repo.githubFullName,
    status: status ?? null,
    message: message || 'unknown GitHub error',
  });
  staticData.coderabbitReviewExtractionRun = run;
  return $input.all();
};

if (Array.isArray(payload?.errors) && payload.errors.length > 0) {
  return recordInaccessible(
    null,
    payload.errors.map((entry) => entry?.message || 'unknown GraphQL error').join(', '),
  );
}

if (payload?.error || payload?.message === 'Not Found') {
  return recordInaccessible(
    payload?.statusCode || payload?.httpCode || null,
    payload?.message || payload?.error?.message || 'GitHub request failed',
  );
}

const pullRequests = payload?.data?.repository?.pullRequests?.nodes || [];
run.inspectedPullRequestCount += pullRequests.length;

for (const pullRequest of pullRequests) {
  const updatedAtMs = Date.parse(String(pullRequest?.updatedAt || ''));
  if (Number.isFinite(updatedAtMs) && Number.isFinite(pollAfterMs) && updatedAtMs < pollAfterMs) {
    continue;
  }

  const unresolvedThreads = (pullRequest?.reviewThreads?.nodes || []).filter((thread) =>
    thread && !thread.isResolved,
  );
  run.inspectedThreadCount += unresolvedThreads.length;

  const matchingThreads = [];

  for (const thread of unresolvedThreads) {
    const matchingCommentIds = [];
    const serializedComments = (thread.comments?.nodes || []).map((comment) => {
      const createdAtMs = Date.parse(String(comment?.createdAt || ''));
      const authorLogin = String(comment?.author?.login || '');
      const id = String(comment?.id || '');
      const isNewCoderabbitComment =
        reviewerLogins.has(authorLogin.toLowerCase()) &&
        Number.isFinite(createdAtMs) &&
        createdAtMs >= pollAfterMs &&
        !knownCommentIds.has(id);

      if (isNewCoderabbitComment) {
        matchingCommentIds.push(id);
        knownCommentIds.add(id);
        run.newCommentIds.push(id);
      }

      return {
        id,
        authorLogin,
        body: String(comment?.body || ''),
        createdAt: String(comment?.createdAt || ''),
        url: String(comment?.url || ''),
        path: String(comment?.path || thread?.path || ''),
        line: comment?.line ?? comment?.originalLine ?? thread?.line ?? null,
        originalLine: comment?.originalLine ?? null,
        diffHunk: String(comment?.diffHunk || ''),
        isNewCoderabbitComment,
      };
    });

    if (matchingCommentIds.length === 0) {
      continue;
    }

    matchingThreads.push({
      threadId: String(thread?.id || ''),
      path: String(thread?.path || ''),
      line: thread?.line ?? null,
      isResolved: Boolean(thread?.isResolved),
      isOutdated: Boolean(thread?.isOutdated),
      matchingCommentCount: matchingCommentIds.length,
      comments: serializedComments,
    });
  }

  if (matchingThreads.length === 0) {
    continue;
  }

  run.extractedPullRequests.push({
    repo: repo.githubFullName,
    owner: repo.githubOwner,
    repoName: repo.githubRepoName,
    pullNumber: pullRequest.number,
    pullRequestTitle: pullRequest.title,
    pullRequestUrl: pullRequest.url,
    selectedProjects: repo.projectNames,
    threadCount: matchingThreads.length,
    matchingCommentCount: matchingThreads.reduce(
      (total, thread) => total + thread.matchingCommentCount,
      0,
    ),
    threads: matchingThreads,
  });
}

run.knownCommentIds = Array.from(knownCommentIds);
staticData.coderabbitReviewExtractionRun = run;

return $input.all();

const staticData = $getWorkflowStaticData('global');
const run = staticData.coderabbitReviewExtractionRun || {};
const persistedState = staticData.coderabbitReviewExtraction || {};
const nextProcessedThreadCommentIds = Array.from(
  new Set([
    ...(Array.isArray(run.newCommentIds)
      ? run.newCommentIds.map((entry) => String(entry))
      : []),
    ...(Array.isArray(persistedState.processedThreadCommentIds)
      ? persistedState.processedThreadCommentIds.map((entry) => String(entry))
      : []),
  ]),
).slice(0, Number(run.rememberedCommentIds || 1000));

staticData.coderabbitReviewExtraction = {
  workflowId: run.workflowId || '',
  lastPolledAt: run.pollStartedAt || new Date().toISOString(),
  selectedReposByFullName: run.selectedReposByFullName || {},
  processedThreadCommentIds: nextProcessedThreadCommentIds,
};
delete staticData.coderabbitReviewExtractionRun;

const pullRequests = Array.isArray(run.extractedPullRequests)
  ? run.extractedPullRequests
  : [];

return [
  {
    json: {
      status: pullRequests.length > 0 ? 'captured' : 'no_matches',
      workflowId: run.workflowId || '',
      pollStartedAt: run.pollStartedAt || new Date().toISOString(),
      previousPollCheckpoint: run.pollAfter || null,
      selectedRepoCount: Number(run.selectedRepoCount || 0),
      selectedRepos: Array.isArray(run.selectedReposSummary)
        ? run.selectedReposSummary
        : [],
      inaccessibleRepos: Array.isArray(run.inaccessibleRepos)
        ? run.inaccessibleRepos
        : [],
      inspectedPullRequestCount: Number(run.inspectedPullRequestCount || 0),
      inspectedThreadCount: Number(run.inspectedThreadCount || 0),
      pullRequestCount: pullRequests.length,
      matchingCommentCount: pullRequests.reduce(
        (total, pullRequest) => total + Number(pullRequest.matchingCommentCount || 0),
        0,
      ),
      pullRequests,
    },
  },
];
